INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_chem_elec_001', 'subj_chemistry', 'topic_electrochemistry', 'Electrolysis is the process of:', '["Using electricity to cause a chemical reaction","Producing electricity from chemicals","Mixing acids and bases","Heating substances"]', 0, 'Electrolysis uses electrical energy to drive non-spontaneous chemical reactions.', 'medium', 'multiple_choice', datetime('now')),
('q_chem_elec_002', 'subj_chemistry', 'topic_electrochemistry', 'In electrolysis, oxidation occurs at the:', '["Cathode","Anode","Both electrodes","Neither electrode"]', 1, 'Oxidation (loss of electrons) occurs at the anode; reduction occurs at the cathode.', 'medium', 'multiple_choice', datetime('now')),
('q_chem_elec_003', 'subj_chemistry', 'topic_electrochemistry', 'A galvanic cell converts:', '["Electrical to chemical energy","Chemical to electrical energy","Heat to electrical energy","Light to electrical energy"]', 1, 'A galvanic (voltaic) cell converts chemical energy into electrical energy through spontaneous reactions.', 'medium', 'multiple_choice', datetime('now')),
('q_chem_elec_004', 'subj_chemistry', 'topic_electrochemistry', 'The electrode where reduction occurs is called:', '["Anode","Cathode","Salt bridge","Electrolyte"]', 1, 'Reduction (gain of electrons) always occurs at the cathode.', 'easy', 'multiple_choice', datetime('now')),
('q_chem_elec_005', 'subj_chemistry', 'topic_electrochemistry', 'Electroplating is used to:', '["Generate electricity","Coat metals with a thin layer of another metal","Produce hydrogen gas","Neutralize acids"]', 1, 'Electroplating deposits a thin layer of metal onto objects for protection or decoration.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_chem_eq_002', 'subj_chemistry', 'topic_equilibrium', 'Le Chatelier''s principle states that a system at equilibrium will:', '["Stop reacting","Shift to oppose any change","Always favor products","Always favor reactants"]', 1, 'Le Chatelier''s principle: a system will shift to counteract any stress applied to it.', 'medium', 'multiple_choice', datetime('now')),
('q_chem_eq_003', 'subj_chemistry', 'topic_equilibrium', 'At equilibrium, the rate of forward reaction:', '["Is zero","Equals the rate of reverse reaction","Is greater than reverse","Is less than reverse"]', 1, 'At equilibrium, forward and reverse reaction rates are equal (dynamic equilibrium).', 'easy', 'multiple_choice', datetime('now')),
('q_chem_eq_004', 'subj_chemistry', 'topic_equilibrium', 'Increasing pressure favors the side with:', '["More moles of gas","Fewer moles of gas","More solid","No effect"]', 1, 'Increased pressure shifts equilibrium toward the side with fewer gas molecules.', 'medium', 'multiple_choice', datetime('now')),
('q_chem_eq_005', 'subj_chemistry', 'topic_equilibrium', 'A catalyst in an equilibrium reaction:', '["Shifts equilibrium right","Shifts equilibrium left","Speeds up reaching equilibrium","Changes the equilibrium constant"]', 2, 'A catalyst speeds up both forward and reverse reactions equally, reaching equilibrium faster.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_phy_kin_002', 'subj_physics', 'topic_kinematics', 'Acceleration is the rate of change of:', '["Distance","Displacement","Velocity","Position"]', 2, 'Acceleration is the rate of change of velocity with respect to time.', 'easy', 'multiple_choice', datetime('now')),
('q_phy_kin_003', 'subj_physics', 'topic_kinematics', 'An object in free fall has acceleration of approximately:', '["5 m/s²","10 m/s²","15 m/s²","20 m/s²"]', 1, 'Acceleration due to gravity is approximately 9.8 m/s² ≈ 10 m/s².', 'easy', 'multiple_choice', datetime('now')),
('q_phy_kin_004', 'subj_physics', 'topic_kinematics', 'The area under a velocity-time graph represents:', '["Acceleration","Displacement","Speed","Force"]', 1, 'The area under a v-t graph gives displacement (distance with direction).', 'medium', 'multiple_choice', datetime('now')),
('q_phy_kin_005', 'subj_physics', 'topic_kinematics', 'If an object moves with constant velocity, its acceleration is:', '["Positive","Negative","Zero","Variable"]', 2, 'Constant velocity means no change in velocity, so acceleration = 0.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_acc_books_002', 'subj_wassce_accounting', 'topic_acc_books', 'The cash book records:', '["Only credit transactions","Only cash and bank transactions","Only purchases","Only sales"]', 1, 'The cash book records all cash and bank transactions (receipts and payments).', 'easy', 'multiple_choice', datetime('now')),
('q_acc_books_003', 'subj_wassce_accounting', 'topic_acc_books', 'The sales day book records:', '["Cash sales only","Credit sales only","All sales","Purchases"]', 1, 'The sales day book (sales journal) records credit sales only.', 'medium', 'multiple_choice', datetime('now')),
('q_acc_books_004', 'subj_wassce_accounting', 'topic_acc_books', 'A petty cash book is used for:', '["Large payments","Small routine expenses","All receipts","Bank transactions only"]', 1, 'Petty cash is used for small, routine business expenses.', 'easy', 'multiple_choice', datetime('now')),
('q_acc_books_005', 'subj_wassce_accounting', 'topic_acc_books', 'The returns inward book records:', '["Goods we return to suppliers","Goods returned by customers","All returns","Damaged goods only"]', 1, 'Returns inward records goods returned by customers (sales returns).', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_acc_ledger_002', 'subj_wassce_accounting', 'topic_acc_ledger', 'The nominal ledger contains:', '["Personal accounts only","Real accounts only","Income and expense accounts","Debtors and creditors only"]', 2, 'The nominal (general) ledger contains income, expense, and capital accounts.', 'medium', 'multiple_choice', datetime('now')),
('q_acc_ledger_003', 'subj_wassce_accounting', 'topic_acc_ledger', 'Posting means:', '["Writing in the journal","Transferring entries from books of original entry to ledger","Balancing accounts","Preparing trial balance"]', 1, 'Posting is transferring journal entries to the appropriate ledger accounts.', 'easy', 'multiple_choice', datetime('now')),
('q_acc_ledger_004', 'subj_wassce_accounting', 'topic_acc_ledger', 'A control account summarizes:', '["All business transactions","Individual accounts in a subsidiary ledger","Cash transactions only","Bank transactions only"]', 1, 'Control accounts (e.g., debtors control) summarize individual accounts from subsidiary ledgers.', 'medium', 'multiple_choice', datetime('now')),
('q_acc_ledger_005', 'subj_wassce_accounting', 'topic_acc_ledger', 'The balance on a debtor''s account is normally:', '["Credit","Debit","Zero","Either debit or credit"]', 1, 'Debtors owe us money (assets), so their accounts normally have debit balances.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_crs_moses_002', 'subj_wassce_crs', 'topic_crs_moses', 'The Passover commemorates:', '["Creation","The Israelites'' deliverance from Egypt","The flood","Abraham''s call"]', 1, 'Passover celebrates God''s deliverance of Israel from Egyptian slavery.', 'easy', 'multiple_choice', datetime('now')),
('q_crs_moses_003', 'subj_wassce_crs', 'topic_crs_moses', 'Moses saw God in the form of:', '["A cloud","A burning bush","A pillar of fire","A dove"]', 1, 'God spoke to Moses from a burning bush that was not consumed.', 'easy', 'multiple_choice', datetime('now')),
('q_crs_moses_004', 'subj_wassce_crs', 'topic_crs_moses', 'The Israelites crossed the Red Sea:', '["By boat","On dry ground when God parted the waters","By swimming","By walking around it"]', 1, 'God parted the Red Sea, allowing the Israelites to cross on dry ground.', 'easy', 'multiple_choice', datetime('now')),
('q_crs_moses_005', 'subj_wassce_crs', 'topic_crs_moses', 'The manna provided to Israel was:', '["Meat","Bread from heaven","Water","Fruit"]', 1, 'Manna was miraculous bread from heaven that God provided daily in the wilderness.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_crs_parab_002', 'subj_wassce_crs', 'topic_crs_parables', 'The Parable of the Good Samaritan teaches about:', '["Prayer","Showing mercy to all people","Fasting","Tithing"]', 1, 'The Good Samaritan parable teaches that we should show mercy to everyone, even strangers.', 'easy', 'multiple_choice', datetime('now')),
('q_crs_parab_003', 'subj_wassce_crs', 'topic_crs_parables', 'In the Parable of the Prodigal Son, the father represents:', '["An earthly king","God''s forgiving love","A wealthy merchant","A strict judge"]', 1, 'The father represents God''s unconditional love and forgiveness for sinners who repent.', 'medium', 'multiple_choice', datetime('now')),
('q_crs_parab_004', 'subj_wassce_crs', 'topic_crs_parables', 'Jesus'' first miracle was performed at:', '["Jerusalem","Bethlehem","Cana","Nazareth"]', 2, 'Jesus'' first miracle was turning water into wine at the wedding in Cana.', 'easy', 'multiple_choice', datetime('now')),
('q_crs_parab_005', 'subj_wassce_crs', 'topic_crs_parables', 'The feeding of the 5000 demonstrates:', '["Jesus'' teaching ability","Jesus'' power to multiply resources","Jesus'' healing power","Jesus'' wealth"]', 1, 'The miracle shows Jesus'' divine power to multiply five loaves and two fish to feed thousands.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_crs_patr_002', 'subj_wassce_crs', 'topic_crs_patriarchs', 'Abraham was originally from:', '["Egypt","Ur of the Chaldeans","Canaan","Jerusalem"]', 1, 'Abraham came from Ur of the Chaldeans (in Mesopotamia) before God called him.', 'medium', 'multiple_choice', datetime('now')),
('q_crs_patr_003', 'subj_wassce_crs', 'topic_crs_patriarchs', 'Isaac was Abraham''s son through:', '["Hagar","Sarah","Keturah","Rebekah"]', 1, 'Isaac was the promised son of Abraham and Sarah, born in their old age.', 'easy', 'multiple_choice', datetime('now')),
('q_crs_patr_004', 'subj_wassce_crs', 'topic_crs_patriarchs', 'Jacob had how many sons?', '["10","12","14","7"]', 1, 'Jacob had 12 sons, who became the 12 tribes of Israel.', 'easy', 'multiple_choice', datetime('now')),
('q_crs_patr_005', 'subj_wassce_crs', 'topic_crs_patriarchs', 'Joseph was sold into slavery by his:', '["Parents","Brothers","Egyptians","Midianites"]', 1, 'Joseph''s jealous brothers sold him to Midianite traders who took him to Egypt.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_eco_dem_002', 'subj_wassce_economics', 'topic_eco_demand', 'An increase in consumer income will:', '["Decrease demand for normal goods","Increase demand for normal goods","Not affect demand","Decrease supply"]', 1, 'Higher income increases purchasing power, raising demand for normal goods.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_dem_003', 'subj_wassce_economics', 'topic_eco_demand', 'Complementary goods are:', '["Goods used together","Goods that replace each other","Luxury goods","Inferior goods"]', 0, 'Complementary goods are used together (e.g., cars and petrol).', 'easy', 'multiple_choice', datetime('now')),
('q_eco_dem_004', 'subj_wassce_economics', 'topic_eco_demand', 'A surplus occurs when:', '["Quantity demanded exceeds quantity supplied","Quantity supplied exceeds quantity demanded","Prices are at equilibrium","There is no market"]', 1, 'A surplus (excess supply) occurs when supply exceeds demand at the current price.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_dem_005', 'subj_wassce_economics', 'topic_eco_demand', 'The law of supply states that:', '["Price and quantity supplied move in opposite directions","Price and quantity supplied move in the same direction","Supply is always constant","Supply equals demand"]', 1, 'Law of supply: higher prices lead to higher quantity supplied (positive relationship).', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_eco_elast_002', 'subj_wassce_economics', 'topic_eco_elasticity', 'Inelastic demand means:', '["Demand is very responsive to price","Demand is not very responsive to price","Demand is constant","There is no demand"]', 1, 'Inelastic demand shows little change in quantity demanded when price changes.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_elast_003', 'subj_wassce_economics', 'topic_eco_elasticity', 'Necessities typically have:', '["Elastic demand","Inelastic demand","Infinite elasticity","Zero elasticity"]', 1, 'Necessities have inelastic demand because people need them regardless of price.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_elast_004', 'subj_wassce_economics', 'topic_eco_elasticity', 'If PED = 0.5, demand is:', '["Elastic","Inelastic","Unit elastic","Perfectly elastic"]', 1, 'PED < 1 indicates inelastic demand.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_elast_005', 'subj_wassce_economics', 'topic_eco_elasticity', 'Cross elasticity measures responsiveness of demand to:', '["Own price changes","Income changes","Price of related goods","Supply changes"]', 2, 'Cross elasticity of demand measures how demand for one good responds to price changes of another.', 'hard', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_eco_intro_002', 'subj_wassce_economics', 'topic_eco_intro', 'Economics studies how to:', '["Make money","Allocate scarce resources to satisfy unlimited wants","Run a business","Manage banks"]', 1, 'Economics is the study of how societies allocate limited resources to meet unlimited wants.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_intro_003', 'subj_wassce_economics', 'topic_eco_intro', 'Microeconomics focuses on:', '["The whole economy","Individual markets and consumers","Government policy only","International trade only"]', 1, 'Microeconomics studies individual economic units like households, firms, and markets.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_intro_004', 'subj_wassce_economics', 'topic_eco_intro', 'A production possibility curve shows:', '["Maximum output combinations with available resources","Only consumer goods","Only capital goods","Unlimited production"]', 0, 'The PPC shows the maximum combinations of goods an economy can produce with its resources.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_intro_005', 'subj_wassce_economics', 'topic_eco_intro', 'In a market economy, prices are determined by:', '["The government","Supply and demand","Producers only","Consumers only"]', 1, 'In a market economy, prices are determined by the interaction of supply and demand.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_eco_mkt_002', 'subj_wassce_economics', 'topic_eco_markets', 'A monopoly exists when:', '["Many firms sell identical products","One firm dominates the market","Firms compete freely","Government controls all prices"]', 1, 'A monopoly is a market structure with a single dominant seller.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_mkt_003', 'subj_wassce_economics', 'topic_eco_markets', 'Perfect competition has:', '["Few sellers","Many sellers of identical products","One seller","Two sellers"]', 1, 'Perfect competition features many sellers offering identical (homogeneous) products.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_mkt_004', 'subj_wassce_economics', 'topic_eco_markets', 'An oligopoly is characterized by:', '["Many small firms","A few large dominant firms","Only one firm","Perfect information"]', 1, 'An oligopoly has a small number of large firms that dominate the market.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_mkt_005', 'subj_wassce_economics', 'topic_eco_markets', 'Monopolistic competition combines features of:', '["Only monopoly","Only perfect competition","Both monopoly and perfect competition","Neither monopoly nor competition"]', 2, 'Monopolistic competition has many firms (like perfect competition) with differentiated products (like monopoly power).', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_eco_mon_002', 'subj_wassce_economics', 'topic_eco_money', 'Fiat money has value because:', '["It is backed by gold","The government declares it legal tender","It can be exchanged for silver","It is made of valuable metal"]', 1, 'Fiat money has value by government decree, not intrinsic value or commodity backing.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_mon_003', 'subj_wassce_economics', 'topic_eco_money', 'The money supply includes:', '["Only coins","Only notes","Currency in circulation and bank deposits","Only gold reserves"]', 2, 'Money supply includes physical currency and various types of bank deposits.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_mon_004', 'subj_wassce_economics', 'topic_eco_money', 'When a central bank increases interest rates:', '["Borrowing becomes cheaper","Borrowing becomes more expensive","Prices fall immediately","Exports increase"]', 1, 'Higher interest rates make borrowing more expensive, discouraging spending.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_mon_005', 'subj_wassce_economics', 'topic_eco_money', 'Deflation means:', '["Rising prices","Falling prices","Stable prices","Rising unemployment only"]', 1, 'Deflation is a sustained decrease in the general price level.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_foods_cat_001', 'subj_wassce_foods', 'topic_fn_catering', 'Institutional catering serves:', '["Only restaurants","Schools, hospitals, and organizations","Only hotels","Only homes"]', 1, 'Institutional catering provides food services to organizations like schools and hospitals.', 'easy', 'multiple_choice', datetime('now')),
('q_foods_cat_002', 'subj_wassce_foods', 'topic_fn_catering', 'A la carte menu means:', '["Fixed price meal","Items priced and ordered separately","Buffet service","Family style dining"]', 1, 'A la carte allows customers to order individual dishes, each priced separately.', 'medium', 'multiple_choice', datetime('now')),
('q_foods_cat_003', 'subj_wassce_foods', 'topic_fn_catering', 'HACCP in catering stands for:', '["Hazard Analysis Critical Control Points","Health And Catering Control Plan","Hygiene Assessment Cooking Control Process","Hospital And Catering Control Program"]', 0, 'HACCP is a systematic food safety management system.', 'hard', 'multiple_choice', datetime('now')),
('q_foods_cat_004', 'subj_wassce_foods', 'topic_fn_catering', 'Silver service is a type of:', '["Self-service","Table service where food is served from platters","Fast food service","Cafeteria service"]', 1, 'Silver service is a formal style where waiters serve food from platters to guests.', 'medium', 'multiple_choice', datetime('now')),
('q_foods_cat_005', 'subj_wassce_foods', 'topic_fn_catering', 'Portion control helps to:', '["Reduce quality","Maintain consistent costs and servings","Increase waste","Slow down service"]', 1, 'Portion control ensures consistent serving sizes and cost management.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_foods_prep_001', 'subj_wassce_foods', 'topic_fn_food_prep', 'Blanching involves:', '["Deep frying","Brief boiling then cooling quickly","Slow roasting","Steaming for hours"]', 1, 'Blanching briefly boils food then rapidly cools it to stop cooking.', 'medium', 'multiple_choice', datetime('now')),
('q_foods_prep_002', 'subj_wassce_foods', 'topic_fn_food_prep', 'Sautéing uses:', '["No fat","Large amounts of water","Small amounts of fat over high heat","Dry heat only"]', 2, 'Sautéing cooks food quickly in a small amount of fat at high temperature.', 'easy', 'multiple_choice', datetime('now')),
('q_foods_prep_003', 'subj_wassce_foods', 'topic_fn_food_prep', 'Braising combines:', '["Only dry heat","Dry and moist heat methods","Only steaming","Only frying"]', 1, 'Braising first sears food (dry heat) then simmers in liquid (moist heat).', 'medium', 'multiple_choice', datetime('now')),
('q_foods_prep_004', 'subj_wassce_foods', 'topic_fn_food_prep', 'Marinating helps to:', '["Make food tougher","Tenderize and add flavor","Remove nutrients","Increase cooking time"]', 1, 'Marinating tenderizes meat and adds flavor through soaking in seasoned liquid.', 'easy', 'multiple_choice', datetime('now')),
('q_foods_prep_005', 'subj_wassce_foods', 'topic_fn_food_prep', 'Stir-frying originated in:', '["France","China","Italy","America"]', 1, 'Stir-frying is a Chinese cooking technique using high heat and quick stirring.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_foods_sci_001', 'subj_wassce_foods', 'topic_fn_food_science', 'Food additives are used to:', '["Only add color","Preserve, enhance, or improve food","Make food unhealthy","Replace nutrients"]', 1, 'Food additives preserve, enhance flavor, improve texture, or add nutrition.', 'easy', 'multiple_choice', datetime('now')),
('q_foods_sci_002', 'subj_wassce_foods', 'topic_fn_food_science', 'Pasteurization kills:', '["All microorganisms","Most harmful bacteria while preserving quality","Only viruses","Only molds"]', 1, 'Pasteurization heats food to kill most harmful bacteria without destroying quality.', 'medium', 'multiple_choice', datetime('now')),
('q_foods_sci_003', 'subj_wassce_foods', 'topic_fn_food_science', 'GMO stands for:', '["Generally Made Organic","Genetically Modified Organism","Good Manufacturing Order","Growth Modified Output"]', 1, 'GMO refers to organisms whose genetic material has been artificially altered.', 'easy', 'multiple_choice', datetime('now')),
('q_foods_sci_004', 'subj_wassce_foods', 'topic_fn_food_science', 'Fermentation is used to make:', '["Fresh vegetables","Yogurt and bread","Raw meat","Plain water"]', 1, 'Fermentation uses microorganisms to produce foods like yogurt, bread, and cheese.', 'easy', 'multiple_choice', datetime('now')),
('q_foods_sci_005', 'subj_wassce_foods', 'topic_fn_food_science', 'Irradiation of food:', '["Cooks the food","Uses radiation to kill bacteria and extend shelf life","Adds vitamins","Changes taste dramatically"]', 1, 'Food irradiation uses controlled radiation to kill pathogens and extend storage.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_foods_diet_001', 'subj_wassce_foods', 'topic_fn_special_diets', 'A diabetic diet limits:', '["Proteins","Carbohydrates and sugars","Vitamins","Water"]', 1, 'Diabetic diets control carbohydrate and sugar intake to manage blood glucose.', 'easy', 'multiple_choice', datetime('now')),
('q_foods_diet_002', 'subj_wassce_foods', 'topic_fn_special_diets', 'A low-sodium diet is prescribed for:', '["Weight gain","Hypertension (high blood pressure)","Anemia","Diabetes"]', 1, 'Reducing sodium helps manage high blood pressure and heart conditions.', 'easy', 'multiple_choice', datetime('now')),
('q_foods_diet_003', 'subj_wassce_foods', 'topic_fn_special_diets', 'Lactose intolerance requires avoiding:', '["All meats","Dairy products containing lactose","All vegetables","Grains"]', 1, 'Lactose intolerant people cannot digest lactose found in dairy products.', 'easy', 'multiple_choice', datetime('now')),
('q_foods_diet_004', 'subj_wassce_foods', 'topic_fn_special_diets', 'Pregnant women need extra:', '["Caffeine","Folic acid and iron","Salt","Sugar"]', 1, 'Folic acid prevents birth defects; iron prevents anemia during pregnancy.', 'easy', 'multiple_choice', datetime('now')),
('q_foods_diet_005', 'subj_wassce_foods', 'topic_fn_special_diets', 'A gluten-free diet avoids:', '["Rice","Wheat, barley, and rye","Potatoes","Corn"]', 1, 'Gluten is found in wheat, barley, and rye; avoided by those with celiac disease.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_geo_clim_002', 'subj_wassce_geography', 'topic_geo_climate', 'Humidity measures:', '["Temperature","Amount of moisture in the air","Wind speed","Rainfall"]', 1, 'Humidity is the amount of water vapor present in the atmosphere.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_clim_003', 'subj_wassce_geography', 'topic_geo_climate', 'An anemometer measures:', '["Rainfall","Wind speed","Temperature","Humidity"]', 1, 'An anemometer is used to measure wind speed.', 'medium', 'multiple_choice', datetime('now')),
('q_geo_clim_004', 'subj_wassce_geography', 'topic_geo_climate', 'Tropical climates are characterized by:', '["Cold winters","High temperatures and rainfall year-round","Four distinct seasons","Dry conditions only"]', 1, 'Tropical climates have consistently high temperatures and significant rainfall.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_clim_005', 'subj_wassce_geography', 'topic_geo_climate', 'Cloud formation occurs when:', '["Air heats up","Water vapor condenses","Wind stops blowing","Temperature rises"]', 1, 'Clouds form when water vapor condenses around particles in the atmosphere.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_geo_gha_002', 'subj_wassce_geography', 'topic_geo_ghana', 'The Volta River is important for:', '["Oil production only","Hydroelectric power generation","Mining only","Fishing only"]', 1, 'The Volta River and Akosombo Dam generate most of Ghana''s electricity.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_gha_003', 'subj_wassce_geography', 'topic_geo_ghana', 'Ghana''s main export crop has traditionally been:', '["Rice","Cocoa","Wheat","Maize"]', 1, 'Cocoa has been Ghana''s primary agricultural export for over a century.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_gha_004', 'subj_wassce_geography', 'topic_geo_ghana', 'The coastal savanna zone in Ghana has:', '["Heavy rainfall","Low rainfall and grasslands","Dense forests","Mountain peaks"]', 1, 'The coastal savanna is a dry zone with grasslands and scattered trees.', 'medium', 'multiple_choice', datetime('now')),
('q_geo_gha_005', 'subj_wassce_geography', 'topic_geo_ghana', 'Gold mining in Ghana is concentrated in:', '["Northern Region","Western and Ashanti Regions","Volta Region","Upper East Region"]', 1, 'Ghana''s major gold deposits are in the Western and Ashanti Regions.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_geo_map_002', 'subj_wassce_geography', 'topic_geo_mapwork', 'A topographic map shows:', '["Only roads","Relief and physical features","Political boundaries only","Population only"]', 1, 'Topographic maps show the terrain and physical features of an area.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_map_003', 'subj_wassce_geography', 'topic_geo_mapwork', 'Bearing is measured in:', '["Kilometers","Degrees from north","Meters","Hours"]', 1, 'Bearing is measured in degrees, clockwise from north (0° to 360°).', 'medium', 'multiple_choice', datetime('now')),
('q_geo_map_004', 'subj_wassce_geography', 'topic_geo_mapwork', 'The scale 1:50,000 means:', '["1 cm represents 50 km","1 cm represents 500 m","1 cm represents 50 m","1 cm represents 5 km"]', 1, 'At 1:50,000, 1 cm on map = 50,000 cm = 500 m in reality.', 'medium', 'multiple_choice', datetime('now')),
('q_geo_map_005', 'subj_wassce_geography', 'topic_geo_mapwork', 'Relief on maps is shown by:', '["Colors only","Contour lines","Symbols only","Lines only"]', 1, 'Contour lines show elevation and the shape of the land (relief).', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_geo_phys_002', 'subj_wassce_geography', 'topic_geo_physical', 'Erosion is the:', '["Building up of landforms","Wearing away and transport of materials","Formation of rocks","Creation of mountains"]', 1, 'Erosion is the wearing away and transportation of rock and soil by natural agents.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_phys_003', 'subj_wassce_geography', 'topic_geo_physical', 'A volcano forms from:', '["Erosion","Molten rock erupting through earth''s surface","River deposition","Glacial movement"]', 1, 'Volcanoes form when magma (molten rock) erupts through the earth''s crust.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_phys_004', 'subj_wassce_geography', 'topic_geo_physical', 'The three main rock types are:', '["Hard, soft, medium","Igneous, sedimentary, metamorphic","Young, old, ancient","Volcanic, river, ocean"]', 1, 'Rocks are classified as igneous, sedimentary, or metamorphic based on formation.', 'medium', 'multiple_choice', datetime('now')),
('q_geo_phys_005', 'subj_wassce_geography', 'topic_geo_physical', 'Deposition occurs when:', '["Moving water speeds up","Moving agents lose energy and drop sediment","Rocks are weathered","Mountains form"]', 1, 'Deposition happens when transport agents slow down and release their load.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_geo_pop_002', 'subj_wassce_geography', 'topic_geo_population', 'Population density is calculated as:', '["Total population × area","Total population ÷ area","Birth rate - death rate","Immigration + emigration"]', 1, 'Population density = Total population / Total area (people per km²).', 'easy', 'multiple_choice', datetime('now')),
('q_geo_pop_003', 'subj_wassce_geography', 'topic_geo_population', 'Rural-urban migration is caused by:', '["Fear of cities","Better opportunities in urban areas","Better farming","More space in cities"]', 1, 'People move to cities seeking jobs, education, and better services.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_pop_004', 'subj_wassce_geography', 'topic_geo_population', 'Natural population growth is:', '["Immigration - emigration","Birth rate - death rate","Total births","Total deaths"]', 1, 'Natural increase = Birth rate - Death rate (excluding migration).', 'medium', 'multiple_choice', datetime('now')),
('q_geo_pop_005', 'subj_wassce_geography', 'topic_geo_population', 'An aging population has more:', '["Children","Working-age adults","Elderly people","Immigrants"]', 2, 'An aging population has a high proportion of elderly people due to low birth rates and longer life expectancy.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_gov_gha_002', 'subj_wassce_government', 'topic_gov_ghana', 'Ghana uses which type of governmental system?', '["Parliamentary","Presidential","Monarchy","Communist"]', 1, 'Ghana operates a presidential system with separation of powers.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_gha_003', 'subj_wassce_government', 'topic_gov_ghana', 'The Council of State advises:', '["Parliament","The President","The Judiciary","Political parties"]', 1, 'The Council of State is a constitutional body that advises the President.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_gha_004', 'subj_wassce_government', 'topic_gov_ghana', 'Ghana''s Parliament has:', '["Two chambers","One chamber (unicameral)","Three chambers","No chambers"]', 1, 'Ghana has a unicameral (single-chamber) Parliament.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_gha_005', 'subj_wassce_government', 'topic_gov_ghana', 'The Electoral Commission is responsible for:', '["Making laws","Conducting elections","Trying cases","Collecting taxes"]', 1, 'The Electoral Commission organizes and supervises all public elections in Ghana.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_gov_intro_002', 'subj_wassce_government', 'topic_gov_intro', 'Sovereignty means:', '["Limited power","Supreme authority of a state","Foreign control","No government"]', 1, 'Sovereignty is the supreme power and authority of a state over its territory.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_intro_003', 'subj_wassce_government', 'topic_gov_intro', 'The state consists of:', '["People only","Territory, population, government, sovereignty","Government only","Army only"]', 1, 'A state has four elements: territory, population, government, and sovereignty.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_intro_004', 'subj_wassce_government', 'topic_gov_intro', 'Power in government refers to:', '["Physical strength","Ability to influence others'' behavior","Wealth","Military force only"]', 1, 'Political power is the ability to influence or control the behavior of others.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_intro_005', 'subj_wassce_government', 'topic_gov_intro', 'Legitimacy means:', '["Illegal rule","Lawful and accepted authority","Foreign control","Absolute power"]', 1, 'Legitimacy is the acceptance and recognition of a government''s right to rule.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_gov_org_002', 'subj_wassce_government', 'topic_gov_organs', 'The Legislature makes:', '["Judgments","Laws","Arrests","Treaties only"]', 1, 'The Legislature (Parliament) is responsible for making laws.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_org_003', 'subj_wassce_government', 'topic_gov_organs', 'The Executive is headed by:', '["The Speaker","The President or Prime Minister","The Chief Justice","The Attorney General"]', 1, 'The Executive branch is led by the head of government (President or PM).', 'easy', 'multiple_choice', datetime('now')),
('q_gov_org_004', 'subj_wassce_government', 'topic_gov_organs', 'Judicial independence means courts:', '["Follow executive orders","Operate free from political interference","Make laws","Enforce laws"]', 1, 'Judicial independence ensures courts can decide cases without political pressure.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_org_005', 'subj_wassce_government', 'topic_gov_organs', 'The doctrine of separation of powers was proposed by:', '["Plato","Montesquieu","Aristotle","Marx"]', 1, 'Montesquieu developed the theory of separation of powers in "The Spirit of Laws."', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_gov_sys_002', 'subj_wassce_government', 'topic_gov_systems', 'In a federal system:', '["All power is central","Power is shared between central and regional governments","There is no central government","Only regions have power"]', 1, 'Federalism divides power between national and state/regional governments.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_sys_003', 'subj_wassce_government', 'topic_gov_systems', 'A unitary system has:', '["Divided power","Centralized power with one government","No constitution","Multiple equal governments"]', 1, 'In a unitary system, the central government holds most power.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_sys_004', 'subj_wassce_government', 'topic_gov_systems', 'In a parliamentary system:', '["The president has all power","The executive is chosen from the legislature","Courts make laws","There is no parliament"]', 1, 'In parliamentary systems, the Prime Minister comes from the majority party in parliament.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_sys_005', 'subj_wassce_government', 'topic_gov_systems', 'A confederation is a:', '["Strong central government","Loose alliance of independent states","Military dictatorship","Monarchy"]', 1, 'A confederation is a union of independent states with a weak central authority.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_hist_au_001', 'subj_wassce_history', 'topic_hist_au', 'The OAU was founded in:', '["1960","1963","1975","1980"]', 1, 'The Organization of African Unity was founded in Addis Ababa in 1963.', 'medium', 'multiple_choice', datetime('now')),
('q_hist_au_002', 'subj_wassce_history', 'topic_hist_au', 'The AU replaced the OAU in:', '["1990","1999","2002","2010"]', 2, 'The African Union officially replaced the OAU in 2002.', 'medium', 'multiple_choice', datetime('now')),
