('q_hist_au_004', 'subj_wassce_history', 'topic_hist_au', 'Pan-Africanism promotes:', '["Colonial rule","African unity and solidarity","Division of Africa","European control"]', 1, 'Pan-Africanism advocates for solidarity and cooperation among people of African descent.', 'easy', 'multiple_choice', datetime('now')),
