('q_hist_nig_001', 'subj_wassce_history', 'topic_hist_nigeria', 'Nigeria gained independence in:', '["1957","1960","1963","1966"]', 1, 'Nigeria gained independence from Britain on October 1, 1960.', 'easy', 'multiple_choice', datetime('now')),
