INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_hist_post_001', 'subj_wassce_history', 'topic_hist_postcolonial', 'A major challenge after independence was:', '["Too much industry","Nation-building and ethnic divisions","Too much food","Excess democracy"]', 1, 'Post-colonial Africa faced challenges of nation-building amid ethnic and regional divisions.', 'easy', 'multiple_choice', datetime('now')),
