('q_hist_ww_001', 'subj_wassce_history', 'topic_hist_world1', 'World War I lasted from:', '["1914-1918","1939-1945","1950-1953","1900-1905"]', 0, 'World War I was fought from 1914 to 1918.', 'easy', 'multiple_choice', datetime('now')),
