INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_hist_cw_001', 'subj_wassce_history', 'topic_hist_world2', 'The Cold War was between:', '["USA and Britain","USA and USSR","Germany and France","China and Japan"]', 1, 'The Cold War was an ideological conflict between the USA and Soviet Union.', 'easy', 'multiple_choice', datetime('now')),
